fun total(order: Order): Money {
    if (!order.isValid()) return Money.ZERO
    return applyDiscount(subtotal(order), order.discount)
}

private fun Order.isValid() = lines.isNotEmpty()
private fun subtotal(order: Order) =
    order.lines.fold(Money.ZERO) { sum, line -> sum + line.amount }
private fun applyDiscount(total: Money, discount: Discount) = total - discount
